/* A model of a counter device /dev/ticker (the sandbox has none: the driver replaces open, ioctl and close).
   Do NOT change the requests: */
#define TICK_GET_VERSION _IOR('t', 1, int)   /* stores the interface version into *arg */
#define TICK_SET_STEP    _IOW('t', 2, int)   /* the counter step is taken from *arg, must be > 0, otherwise EINVAL */
#define TICK_ADVANCE     _IO('t', 3)         /* adds the step to the counter, no argument */
#define TICK_GET_TOTAL   _IOR('t', 4, long)  /* stores the counter value into *arg */

/* ticker_run: open path (O_RDWR), check that the interface version is 2 (otherwise the error is EPROTO),
   set the step to step, call TICK_ADVANCE n times, read TICK_GET_TOTAL and return it.
   On any failure return -errno of the cause (the error of open, ioctl or EPROTO), but close the
   descriptor first: close must not replace the cause. */
